from django.http import JsonResponse
from django.views import View
from django.utils.decorators import method_decorator
from django.contrib.auth.decorators import login_required
from asgiref.sync import sync_to_async
import json
from .models import CustomerServiceContract

@method_decorator(login_required, name="dispatch")
class AgentAsyncToolDispatchView(View):
    async def post(self, request):
        payload = json.loads(request.body)
        tool_call = payload.get("tool_call", {})
        tool_name = tool_call.get("name")
        tool_args = tool_call.get("args", {})

        if tool_name == "fetch_contract_sla":
            contract_code = tool_args.get("contract_code")
            # Verify that the authenticated client owns or is assigned to the contract
            contract = await sync_to_async(
                lambda: CustomerServiceContract.objects.filter(
                    code=contract_code,
                    client_account__members=request.user
                ).first()
            )()

            if not contract:
                return JsonResponse({"error": "Contract not found or access denied"}, status=404)

            return JsonResponse({
                "contract_code": contract.code,
                "tier": contract.service_tier,
                "monthly_retainer_usd": str(contract.monthly_retainer),
                "penalty_terms": contract.penalty_clauses
            })

        return JsonResponse({"error": "Tool not registered"}, status=400)
